export default function Sidebar() {
  
  const [isOpen, setIsOpen] = React.useState(false);

  /* =========================================================
      ESCAPE KEY
  ========================================================= */
  React.useEffect(() => {
    const handleEscape = (event) => {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    };

    document.addEventListener("keydown", handleEscape);

    return () => {
      document.removeEventListener("keydown", handleEscape);
    };
  }, []);

  /* =========================================================
      LOCK BODY SCROLL WHEN MOBILE SIDEBAR IS OPEN
  ========================================================= */
  React.useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }

    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  const closeMobileMenu = () => {
    setIsOpen(false);
  };

  return (
    <>
      {/* =====================================================
          MOBILE MENU BUTTON
      ====================================================== */}
      <button
        type="button"
        onClick={() => setIsOpen(true)}
        aria-label="Open student navigation"
        aria-expanded={isOpen}
        className={`
          fixed
          left-4
          top-4
          z-[80]
          flex
          h-11
          w-11
          items-center
          justify-center
          rounded-xl
          border
          border-slate-200
          bg-white
          text-slate-700
          shadow-[0_3px_12px_rgba(15,23,42,0.08)]
          transition-all
          duration-200
          hover:bg-slate-50
          hover:shadow-md
          active:scale-95
          md:hidden
          ${isOpen ? "pointer-events-none opacity-0" : "opacity-100"}
        `}
      >
        <Menu
          className="h-6 w-6"
          strokeWidth={2}
        />
      </button>

      {/* =====================================================
          MOBILE BACKDROP
      ====================================================== */}
      <div
        onClick={closeMobileMenu}
        aria-hidden="true"
        className={`
          fixed
          inset-0
          z-[60]
          bg-slate-950/40
          backdrop-blur-[2px]
          transition-opacity
          duration-300
          md:hidden
          ${
            isOpen
              ? "pointer-events-auto opacity-100"
              : "pointer-events-none opacity-0"
          }
        `}
      />

      {/* =====================================================
          SIDEBAR
      ====================================================== */}
      <aside
        className={`
          fixed
          inset-y-0
          left-0
          z-[70]
          flex
          h-screen
          max-h-screen
          w-[300px]
          md:w-[250px]
          shrink-0
          flex-col
          overflow-hidden
          border-r
          border-slate-100
          bg-white
          px-5
          md:px-4
          py-6
          md:py-5
          font-sans
          select-none
          shadow-[4px_0_20px_rgba(15,23,42,0.035)]
          transition-transform
          duration-300
          ease-in-out
          md:translate-x-0
          md:transition-none
          ${
            isOpen
              ? "translate-x-0"
              : "-translate-x-full"
          }
        `}
      >
        {/* =====================================================
            MOBILE CLOSE BUTTON
        ====================================================== */}
        <button
          type="button"
          onClick={closeMobileMenu}
          aria-label="Close student navigation"
          className="
            absolute
            right-4
            top-4
            z-20
            flex
            h-9
            w-9
            items-center
            justify-center
            rounded-lg
            text-slate-400
            transition-all
            duration-200
            hover:bg-slate-100
            hover:text-slate-700
            active:scale-95
            md:hidden
          "
        >
          <X
            className="h-5 w-5"
            strokeWidth={2}
          />
        </button>

        {/* =====================================================
            SIDEBAR INNER
        ====================================================== */}
        <div className="flex h-full min-h-0 flex-col">

          {/* ===================================================
              BRAND
          ==================================================== */}
          <div className="shrink-0 px-2 pb-6 md:pb-6 pt-1 text-center md:text-left">
            <h1 className="text-xl md:text-[15px] font-bold tracking-tight text-[#28356f]">
              LMS{" "}
              <span className="font-semibold">
                SYSTEM
              </span>
            </h1>

            <p className="mt-1 md:mt-0.5 text-xs md:text-[8px] font-medium uppercase tracking-[0.08em] text-slate-400">
             Tutor Portal
            </p>
          </div>

          {/* ===================================================
              NAVIGATION
          ==================================================== */}
          <nav
            aria-label="Student navigation"
            className="
              min-h-0
              flex-1
              space-y-2
              md:space-y-1
              overflow-x-hidden
              overflow-y-auto
              pr-1
            "
          >
            {navigationItems.map((item) => {
              const Icon = item.icon;

              return (
                <NavLink
                  key={item.path}
                  to={item.path}
                  onClick={closeMobileMenu}
                  className={({ isActive }) => `
                    group
                    relative
                    flex
                    min-h-[48px]
                    md:min-h-[40px]
                    w-full
                    items-center
                    rounded-[11px]
                    md:rounded-[9px]
                    px-3.5
                    md:px-2.5
                    py-3
                    md:py-2
                    transition-all
                    duration-200
                    ${
                      isActive
                        ? "bg-indigo-50/80 text-indigo-600"
                        : "text-slate-500 md:text-slate-400 hover:bg-slate-50 hover:text-slate-700"
                    }
                  `}
                >
                  {({ isActive }) => (
                    <>
                      {/* Active Indicator */}
                      {isActive && (
                        <span
                          className="
                            absolute
                            -right-[21px]
                            md:-right-[17px]
                            top-1/2
                            h-6
                            w-[3px]
                            -translate-y-1/2
                            rounded-l-full
                            bg-indigo-600
                          "
                        />
                      )}

                      {/* Icon */}
                      <span
                        className="
                          flex
                          h-6
                          w-6
                          md:h-5
                          md:w-5
                          shrink-0
                          items-center
                          justify-center
                        "
                      >
                        {typeof Icon === "function" || (typeof Icon === "object" && Icon !== null && !React.isValidElement(Icon)) ? (
                          <Icon
                            className={`
                              h-5
                              w-5
                              md:h-[16px]
                              md:w-[16px]
                              transition-colors
                              duration-200
                              ${
                                isActive
                                  ? "text-indigo-600"
                                  : "text-slate-500 md:text-slate-400 group-hover:text-slate-600"
                              }
                            `}
                            strokeWidth={
                              isActive ? 2.3 : 1.8
                            }
                          />
                        ) : (
                          Icon
                        )}
                      </span>

                      {/* Label */}
                      <span
                        className={`
                          ml-3.5
                          md:ml-2
                          min-w-0
                          flex-1
                          truncate
                          whitespace-nowrap
                          text-sm
                          md:text-[10px]
                          leading-none
                          ${
                            isActive
                              ? "font-semibold text-indigo-600"
                              : "font-medium text-slate-600 md:text-slate-400 group-hover:text-slate-700"
                          }
                        `}
                      >
                        {item.name}
                      </span>
                    </>
                  )}
                </NavLink>
              );
            })}
          </nav>

          {/* ===================================================
              SUPPORT CARD
          ==================================================== */}
          <div className="relative mt-6 md:mt-4 shrink-0 px-1 pt-8">
            <div
              className="
                relative
                overflow-visible
                rounded-[14px]
                bg-gradient-to-b
                from-indigo-600
                to-indigo-800
                px-4
                md:px-3
                pb-4
                md:pb-3
                pt-9
                md:pt-7
                text-center
                shadow-md
                shadow-indigo-100
              "
            >
              {/* Floating Help Icon */}
              <div
                className="
                  absolute
                  -top-6
                  left-1/2
                  flex
                  h-12
                  w-12
                  md:h-11
                  md:w-11
                  -translate-x-1/2
                  items-center
                  justify-center
                  rounded-full
                  border-[3px]
                  border-white
                  bg-indigo-700
                  shadow-md
                "
              >
                <HelpCircle
                  className="h-6 w-6 md:h-5 md:w-5 text-white"
                  strokeWidth={1.8}
                />
              </div>

              <h3 className="text-xs md:text-[10px] font-semibold text-white">
                Need Help?
              </h3>
              <p className="mt-1 text-[10px] md:text-[9px] text-indigo-200">
                Check our documentation or reach out to support.
              </p>
            </div>
          </div>

        </div>
      </aside>
    </>
  );
}